    #[test]
    fn category_from_tags_defaults_to_other() {
        assert_eq!(
            category_from_tags(&["critical".to_string(), "ui".to_string()]),
            "other"
        );
        assert_eq!(category_from_tags(&[]), "other");
    }

    #[test]
    fn quick_capture_with_tag_uses_category() {
