    #[test]
    fn delivery_declined_saves_locally_only() {
        let temp = TempDir::new().unwrap();
        let store = create_test_store(&temp);
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("feedback_deliver", "no");

