        };

        let resolver = resolver_with_mock(&server);
        let resolved = resolver.resolve(&config).unwrap();

        // Base steps appear in result
        assert!(resolved.steps.contains_key("install"));
        assert_eq!(
            resolved.steps["install"].execution.command,
